// 纯C全流式特征重构与网络前向推导
int gesture_algorithm_process(const ImuData_t* window_buffer, float* out_probs) {
    static float feature_matrix[50][9];
    float window_energy = 0.0f;

    // 1. 构建 9通道特征空间并计算原始 6轴波动总能量 (Energy)
    for (int i = 0; i < 50; i++) {
        feature_matrix[i][0] = (float)window_buffer[i].gyro_x;
        feature_matrix[i][1] = (float)window_buffer[i].gyro_y;
        feature_matrix[i][2] = (float)window_buffer[i].gyro_z;
        feature_matrix[i][3] = (float)window_buffer[i].acc_x;
        feature_matrix[i][4] = (float)window_buffer[i].acc_y;
        feature_matrix[i][5] = (float)window_buffer[i].acc_z;

        // 计算 Jerk (一阶加速度差分)
        if (i == 0) {
            feature_matrix[i][6] = 0.0f;
            feature_matrix[i][7] = 0.0f;
            feature_matrix[i][8] = 0.0f;
        } else {
            feature_matrix[i][6] = feature_matrix[i][3] - (float)window_buffer[i-1].acc_x;
            feature_matrix[i][7] = feature_matrix[i][4] - (float)window_buffer[i-1].acc_y;
            feature_matrix[i][8] = feature_matrix[i][5] - (float)window_buffer[i-1].acc_z;
        }

        // 统计时域方差前级所需的能量和
        float frame_energy = 0.0f;
        for(int j=0; j<6; j++) frame_energy += feature_matrix[i][j] * feature_matrix[i][j];
        window_energy += frame_energy / 50.0f; // 粗略估算局部能量域分布
        
        // 2. 实时 Z-Score 转换
        for (int j = 0; j < 9; j++) {
            feature_matrix[i][j] = (feature_matrix[i][j] - SCALER_MEANS[j]) / SCALER_SCALES[j];
        }
    }

    // 3. 1D-CNN 推理层 1: Conv1D (输入 50x9 -> 输出 46x16)
    static float conv1_out[46][16];
    for (int t = 0; t < 46; t++) {
        for (int f = 0; f < 16; f++) {
            float sum = conv1_biases[f];
            for (int k = 0; k < 5; k++) {
                for (int c = 0; c < 9; c++) {
                    sum += feature_matrix[t + k][c] * conv1_weights[k][c][f];
                }
            }
            conv1_out[t][f] = sum > 0.0f ? sum : 0.0f; // ReLU
        }
    }

    // 4. 推理层 2: MaxPooling1D (输入 46x16 -> 输出 23x16)
    static float pool_out[23][16];
    for (int t = 0; t < 23; t++) {
        for (int f = 0; f < 16; f++) {
            float val1 = conv1_out[t * 2][f];
            float val2 = conv1_out[t * 2 + 1][f];
            pool_out[t][f] = val1 > val2 ? val1 : val2;
        }
    }

    // 5. 推理层 3: Conv1D_1 (输入 23x16 -> 输出 21x32)
    static float conv2_out[21][32];
    for (int t = 0; t < 21; t++) {
        for (int f = 0; f < 32; f++) {
            float sum = conv2_biases[f];
            for (int k = 0; k < 3; k++) {
                for (int c = 0; c < 16; c++) {
                    sum += pool_out[t + k][c] * conv2_weights[k][c][f];
                }
            }
            conv2_out[t][f] = sum > 0.0f ? sum : 0.0f; // ReLU
        }
    }

    // 6. 推理层 4: GlobalAveragePooling1D (输入 21x32 -> 输出 32)
    float gap_out[32] = {0};
    for (int f = 0; f < 32; f++) {
        float sum = 0.0f;
        for (int t = 0; t < 21; t++) sum += conv2_out[t][f];
        gap_out[f] = sum / 21.0f;
    }

    // 7. 推理层 5: Dense + Softmax (输入 32 -> 输出 5)
    float max_val = -9999.0f;
    float sum_exp = 0.0f;
    float dense_out[5];
    for (int o = 0; o < 5; o++) {
        float sum = dense_biases[o];
        for (int i = 0; i < 32; i++) sum += gap_out[i] * dense_weights[i][o];
        dense_out[o] = sum;
        if (sum > max_val) max_val = sum; // 用于防止Softmax溢出
    }
    for (int o = 0; o < 5; o++) {
        out_probs[o] = expf(dense_out[o] - max_val);
        sum_exp += out_probs[o];
    }
    int pred_label = 4;
    float max_prob = 0.0f;
    for (int o = 0; o < 5; o++) {
        out_probs[o] /= sum_exp;
        if (out_probs[o] > max_prob) {
            max_prob = out_probs[o];
            pred_label = o;
        }
    }

    // 8. 移交嵌入式后处理状态机决策
    return simulate_embedded_state_machine(pred_label, max_prob, window_energy);
}

// 核心状态机：生物力学时序锁 + 微动作能量上限锁
int simulate_embedded_state_machine(int pred_label, float pred_prob, float window_energy) {
    float THRESHOLDS[4] = { 0.75f, 0.80f, 0.85f, 0.75f };
    if (pred_label == GESTURE_OTHERS) return -1;
    if (pred_prob < THRESHOLDS[pred_label]) return -1;

    // 🔒 锁1: 微动作能量上限锁
    if (pred_label == GESTURE_PINCH && window_energy > AUTO_PINCH_ENERGY_THRESH) {
        return -1; // 强制熔断由于Clench暴力振动误报的Pinch
    }

    // 🔒 锁2: 生物力学时序锁 (Sequence Lock)
    if (pred_label == GESTURE_DOWN && arm_state == 0) return -1; // 拦截无抬腕情况下的放下
    if (pred_label == GESTURE_UP && arm_state == 1) return -1;   // 拦截看表期间的多重连击

    // 冷却机制判断
    uint32_t current_time_ms = 0; // 该值将由上层具体运行时的时间戳传入
    // 允许通过的状态更新
    if (pred_label == GESTURE_UP) arm_state = 1;
    else if (pred_label == GESTURE_DOWN) arm_state = 0;

    return pred_label;
}